const candidates = $input.all()
  .map(i => i.json)
  .filter(d => d.domain);

// One item carrying the whole batch: the Moz url_metrics endpoint accepts up
// to 50 targets per call, so the entire list costs one API request.
return [{
  json: {
    domains: candidates.map(d => d.domain).slice(0, 50),
    candidates,
  },
}];

const candidates = $('Prepare Batch').first().json.candidates;

// Moz echoes each target back in the result's page field. Keying on it keeps
// every metric attached to its own domain even when some targets fail.
const mozByDomain = new Map();
const mozResults = ($json.results || []).filter(r => r && r.page);
for (const r of mozResults) {
  mozByDomain.set(r.page.replace(/\/$/, '').toLowerCase(), r);
}

const records = candidates.map(c => {
  const m = mozByDomain.get(c.domain.toLowerCase()) || {};
  return {
    domain: c.domain,
    registered_date: c.registered_date || '',
    age: c.age ?? '',
    expiry_stage: c.status || '',
    domain_authority: m.domain_authority ?? '',
    page_authority: m.page_authority ?? '',
    spam_score: (m.spam_score === -1 ? '' : m.spam_score) ?? '',
    linking_root_domains: m.root_domains_to_root_domain ?? '',
  };
});

records.sort((a, b) => (Number(b.domain_authority) || 0) - (Number(a.domain_authority) || 0) || a.domain.localeCompare(b.domain));

const keyword = $('Set Target').first().json.keyword;
const scored = records.filter(r => r.domain_authority !== '').length;

const lines = records.map(r => {
  const parts = [
    r.domain,
    `  registered ${r.registered_date || 'not reported'}, stage: ${r.expiry_stage || 'not reported'}`,
    `  DA ${r.domain_authority === '' ? 'n/a' : r.domain_authority}, PA ${r.page_authority === '' ? 'n/a' : r.page_authority}, spam ${r.spam_score === '' ? 'n/a' : r.spam_score}, linking root domains ${r.linking_root_domains === '' ? 'n/a' : r.linking_root_domains}`,
  ];
  return parts.join('\n');
});

const body = [
  `Expired domain candidates for "${keyword}"`,
  'Expired domains across the deletion lifecycle (expired, redemption, pending delete), scored with Moz.',
  '',
  `${records.length} candidates, ${scored} scored, sorted by Domain Authority. Empty metrics mean Moz returned nothing for that name.`,
  '',
  records.length ? lines.join('\n\n') : 'No expired domains matched the keyword today.',
  '',
  'Records are attached as CSV.',
].join('\n');

return [{
  json: {
    subject: `${keyword}: ${records.length} expired domain candidates`,
    message: body,
    records,
  },
}];
